create table if not exists public.security_review_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,workspace_id uuid not null references public.workspaces(id)on delete cascade,user_id uuid references auth.users(id),event_type text not null check(event_type in('permission_denied','authorization_failed','rate_limited','suspicious_request','security_review')),resource text not null,metadata jsonb not null default'{}',created_at timestamptz not null default now());
create index if not exists security_review_events_observability_idx on public.security_review_events(organization_id,workspace_id,event_type,created_at desc);
alter table public.security_review_events enable row level security;create policy "security review administrators read"on public.security_review_events for select to authenticated using(public.current_workspace_role(workspace_id)in('organization_owner','organization_admin')or(auth.jwt()->'app_metadata'->>'role')='super_admin');
create or replace function public.enterprise_security_rls_audit(p_workspace_id uuid)returns table(tables integer,enabled integer,fully_covered integer,missing_rls text[],missing_policies text[])language plpgsql stable security definer set search_path=public,pg_catalog as $$begin if public.current_workspace_role(p_workspace_id)not in('organization_owner','organization_admin')and(auth.jwt()->'app_metadata'->>'role')<>'super_admin'then raise exception'administrator access required';end if;return query with t as(select tablename,rowsecurity from pg_tables where schemaname='public'),p as(select tablename,array_agg(distinct cmd)commands from pg_policies where schemaname='public'group by tablename),a as(select t.tablename,t.rowsecurity,coalesce(p.commands,'{}')commands from t left join p using(tablename))select count(*)::integer,count(*)filter(where rowsecurity)::integer,count(*)filter(where rowsecurity and('ALL'=any(commands)or('SELECT'=any(commands)and'INSERT'=any(commands)and'UPDATE'=any(commands)and'DELETE'=any(commands))))::integer,coalesce(array_agg(tablename order by tablename)filter(where not rowsecurity),'{}'),coalesce(array_agg(tablename order by tablename)filter(where rowsecurity and not('ALL'=any(commands)or('SELECT'=any(commands)and'INSERT'=any(commands)and'UPDATE'=any(commands)and'DELETE'=any(commands)))),'{}')from a;end$$;
revoke all on public.security_review_events from anon;grant select on public.security_review_events to authenticated;revoke all on function public.enterprise_security_rls_audit(uuid)from public;grant execute on function public.enterprise_security_rls_audit(uuid)to authenticated;
